//! 🧪️ Resident post custody follows one actual Source and Work bank.
use semio_framework_value_clone_source::{OriginalSourceOwner,OriginalSourceMode};
use semio_framework_value_retirement::RetireOwned;
use semio_framework_value_retained_clone::*;
use semio_framework_value_clone_source_testing::{FixtureSourceBirth,FixtureCloseStep};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use std::mem::ManuallyDrop;

struct Envelope{value:String,tag:u64}
impl RetireOwned for Envelope{type RetirementCursor=<(String,u64) as RetireOwned>::RetirementCursor;fn retirement_seed(self)->Self::RetirementCursor{(self.value,self.tag).retirement_seed()}fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<Self::RetirementCursor>())}fn controlled_retirement_supported()->bool{true}}
impl semio_framework_value_clone_source::OriginalSourceProjection<String> for Envelope{fn projection_work_demand(&self)->Result<u64,ValueError>{Ok(1)}fn project_source<'r,'a>(&'a self,effect:&mut RetainedAllocationEffect<'_>,reply:semio_framework_value_clone_source::OriginalProjectionReply<'r,'a,String>)->Result<OriginalEffectReplyComplete<'r,std::ptr::NonNull<String>,ValueError>,ValueError>{assert!(effect.performed(1)?);Ok(reply.complete(Ok(&self.value)))}fn recover_source_projection<'r,'a>(&'a self,_:&mut RetainedAllocationEffect<'_>,reply:semio_framework_value_clone_source::OriginalProjectionReply<'r,'a,String>)->Result<OriginalEffectReplyComplete<'r,std::ptr::NonNull<String>,ValueError>,ValueError>{Ok(reply.pending())}}
#[derive(Clone,Copy,PartialEq,Eq,Debug)]enum Op{Capture,Original,Drive,Mutable,Return,Retire}
struct Context<'a>{source:RetainedCloneRef<'a,u64>,turn:OriginalSourceTurnIdentity,op:Op,body:usize}
struct Producer{post:ManuallyDrop<OriginalSourceOwner<String,Envelope>>,input:ManuallyDrop<Option<Envelope>>,returned:ManuallyDrop<Option<Envelope>>,retirement:ManuallyDrop<RetainedCloneClose>,inner:Option<OriginalEffectAction<RetainedCloneStep,ValueError>>,inner_reply:ManuallyDrop<Option<Result<RetainedCloneStep,ValueError>>>,source:(u64,usize,usize,usize),turn:OriginalSourceTurnIdentity,selected:Option<(OriginalEffectInvocationIdentity,Op,usize)>}
impl Producer{fn empty(&self)->bool{self.selected.is_none()&&self.inner.is_none()&&self.inner_reply.is_none()&&self.input.is_none()&&self.returned.is_none()&&self.post.terminal_is_empty()&&self.retirement.is_empty()}fn dispatch<'r>(&mut self,c:&mut Context<'_>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>,recover:bool)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let invocation=effect.invocation().ok_or_else(||ValueError::invariant("post law invocation absent"))?;let mode=if recover{OriginalEffectCallbackMode::Recover}else{OriginalEffectCallbackMode::Receive};if invocation.mode()!=mode{return Err(ValueError::invariant("post law invocation changed"))}let key=(invocation.identity(),c.op,c.body);if recover{if self.selected!=Some(key){return Err(ValueError::invariant("post law recovery changed"))}}else if self.selected.is_some(){return Err(ValueError::invariant("post law action occupied"))}let state=self;let mut scope=reply.progress().scope(&mut state.selected,key)?;match c.op{Op::Capture|Op::Return=>{if recover{return Err(ValueError::invariant("native post transfer cannot recover without a reply"))}let mut result=None;let inner=OriginalEffectReply::borrow(&mut result)?;let done=if c.op==Op::Capture{state.post.capture_into(&mut state.input,effect,inner)?}else{state.post.return_into(&mut state.returned,effect,inner)?};drop(done);let done=semio_framework_value_retirement::forward_original_value_reply(&mut result,scope.borrow()?)?;drop(done)},Op::Original|Op::Mutable=>{let mode=if c.op==Op::Original{OriginalSourceMode::Original}else{OriginalSourceMode::Unique};let done=if recover{state.post.recover_prepare_into(mode,c.body,effect,scope.borrow()?)?}else{state.post.prepare_into(mode,c.body,effect,scope.borrow()?)?};drop(done)},Op::Drive=>{let frame=state.post.projection_frame(effect)?;let mut context=frame.context()?;let ready=frame.authority()?.drive(&mut context,effect,&mut state.inner)?;if recover&&ready{if !state.inner.as_mut().ok_or_else(||ValueError::invariant("nested action absent"))?.transfer_reply(&mut state.inner_reply)?{return Ok(scope.forwarded())}frame.authority()?.finish(&mut state.inner)?;let done=semio_framework_value_retirement::forward_original_value_reply(&mut state.inner_reply,scope.borrow()?)?;drop(done)}},Op::Retire=>{if state.retirement.is_empty(){if recover{return Err(ValueError::invariant("native retirement birth cannot recover without a reply"))}let turn=state.retirement.begin_granted(&mut state.returned,effect);let done=scope.borrow()?.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into));drop(done)}else{let done=if recover{state.retirement.recover_step_into(effect,scope.borrow()?)?}else{state.retirement.step_into(effect,scope.borrow()?)?};drop(done)}}}Ok(scope.forwarded())}}
impl Drop for Producer{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.empty());unsafe{ManuallyDrop::drop(&mut self.post);ManuallyDrop::drop(&mut self.input);ManuallyDrop::drop(&mut self.returned);ManuallyDrop::drop(&mut self.retirement);ManuallyDrop::drop(&mut self.inner_reply)}}}
impl OriginalEffectProducer for Producer{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a> where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.source.reference_identity()!=self.source||c.turn!=self.turn{return Err(ValueError::invariant("post law changed original Source"))}Ok(())}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.turn)}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,false)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.dispatch(c,e,r,true)}}

struct ProducerLoan<'a>{producer:&'a mut Producer}
impl std::ops::Deref for ProducerLoan<'_>{type Target=Producer;fn deref(&self)->&Self::Target{self.producer}}
impl ProducerLoan<'_>{fn empty(&self)->bool{self.producer.empty()}}
impl OriginalEffectProducer for ProducerLoan<'_>{type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a>where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{self.producer.validate_context(c)}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{self.producer.source_turn(c)}fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.producer.receive(c,e,r)}fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{self.producer.recover(c,e,r)}}
fn grant_for(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn generic_source_owner_projects_target_and_returns_authority(){let law:serde_json::Value=serde_json::from_str(include_str!("owner.json")).unwrap();for cut in law["cancellationCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap();let text=law["value"].as_str().unwrap().to_owned();let pointer=text.as_ptr();let mut source=RetainedCloneSource::<u64>::from_owner(73);let id=source.borrow().reference_identity();let mut input=Some(Envelope{value:text,tag:law["authorityTag"].as_u64().unwrap()});let turn=source.with_bank(|_,bank|bank.source_witness().identity()).unwrap();let mut resident=Producer{post:ManuallyDrop::new(OriginalSourceOwner::default()),input:ManuallyDrop::new(input.take()),returned:ManuallyDrop::new(None),retirement:ManuallyDrop::new(Default::default()),inner:None,inner_reply:ManuallyDrop::new(None),source:id,turn,selected:None};let mut authority=Some(OriginalEffectAuthority::new(ProducerLoan{producer:&mut resident}));let mut op=Op::Capture;let mut action=None;let mut answer=None;let mut observed=(0usize,0usize);for tick in 0..4096{let p=authority.as_ref().unwrap();if op==Op::Original&&tick as u64>=cut{op=Op::Mutable}if op==Op::Original&&p.inspect(|p|p.post.demand(OriginalSourceMode::Original,4096).unwrap().is_none()){p.inspect(|p|{let value=p.post.original().unwrap().get();assert_eq!(value.as_ptr(),pointer);assert_eq!(value,law["value"].as_str().unwrap())});op=Op::Mutable}if op==Op::Mutable&&p.inspect(|p|p.post.demand(OriginalSourceMode::Unique,4096).unwrap().is_none()){p.inspect(|p|assert_eq!(p.post.unique().unwrap().value.as_ptr(),pointer));op=Op::Return}if op==Op::Retire&&p.inspect(ProducerLoan::empty){break}let selected=if matches!(op,Op::Original|Op::Mutable)&&p.inspect(|p|p.post.projection_drive_required_for(if op==Op::Mutable{OriginalSourceMode::Unique}else{OriginalSourceMode::Original}).unwrap()){Op::Drive}else{op};let(d,work)=p.inspect(|p|match selected{Op::Capture=>(OriginalSourceOwner::<String,Envelope>::capture_demand(),1),Op::Original|Op::Drive=>{let mode=if op==Op::Mutable{OriginalSourceMode::Unique}else{OriginalSourceMode::Original};(p.post.demand(mode,4096).unwrap().unwrap(),p.post.work_demand(mode,4096).unwrap())},Op::Mutable=>(p.post.demand(OriginalSourceMode::Unique,4096).unwrap().unwrap(),p.post.work_demand(OriginalSourceMode::Unique,4096).unwrap()),Op::Return=>(p.post.return_demand(),1),Op::Retire=>{assert!(!p.retirement.requires_original_birth());assert!(!p.retirement.requires_original_control());(p.retirement.next_owner_demands::<Envelope>(p.returned.is_some(),&None,4096).unwrap(),p.retirement.next_owner_work::<Envelope>(p.returned.is_some(),&None,4096).unwrap())}});assert!(d.copy_bytes<=law["maximumCopyBytes"].as_u64().unwrap() as usize,"step {} {:?}: {:?}; stage={} source={} frame={} admission={}",tick,selected,d,std::mem::size_of::<StagedSourceAdmission<String,Envelope>>(),std::mem::size_of::<RetainedCloneSource<String,Envelope>>(),std::mem::size_of::<OriginalProjectionFrame<String,Envelope>>(),std::mem::size_of::<RetainedCloneSourceAdmission<String,Envelope>>());let grant=grant_for(d);loop{let((poll,actual),heap)=source.with_bank(|original,bank|{let observed_step=observe(||bank.run_with_source(grant,work,|effect,witness|{let before=effect.performed_work();let mut context=Context{source:original,turn:witness.identity(),op:selected,body:4096};let ready=authority.as_mut().unwrap().drive(&mut context,effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work})}else{RetainedWorkPoll::Pending{work}}}));observed.0+=observed_step.1.0;observed.1+=observed_step.1.1;if let(RetainedWorkPoll::Complete(_),_)=&observed_step.0{assert!(action.as_mut().unwrap().transfer_reply(&mut answer).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=answer.as_ref().unwrap().as_ref().unwrap();assert_eq!(observed,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),grant,observed);observed=(0,0)}observed_step}).unwrap();if let Some(actual)=actual{assert_eq!(actual,heap.0)}if let RetainedWorkPoll::Complete(done)=poll{done.result.unwrap();answer.take().unwrap().unwrap();break}}if op==Op::Capture{op=Op::Original}else if op==Op::Return{authority.as_ref().unwrap().inspect(|p|{let value=p.returned.as_ref().unwrap();assert_eq!(value.value.as_ptr(),pointer);assert_eq!(value.value,law["value"].as_str().unwrap());assert_eq!(value.tag,law["authorityTag"].as_u64().unwrap())});op=Op::Retire}}assert!(authority.as_ref().unwrap().inspect(ProducerLoan::empty));
 source.with_bank(|original,bank|{let d=OriginalEffectAuthority::<ProducerLoan<'_>>::producer_transfer_demand().unwrap();assert!(d.copy_bytes<=4096,"actual owner handoff copies {}",d.copy_bytes);let grant=grant_for(d);let mut producer=None;let((poll,_),heap)=observe(||bank.run_with_source(grant,1,|effect,witness|{let context=Context{source:original,turn:witness.identity(),op:Op::Retire,body:0};RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&context,&mut producer,effect))}));let RetainedWorkPoll::Complete(done)=poll else{panic!("post producer transfer pending")};let progress=done.result.unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap);let witness=unsafe{RetainedCursorRelease::native(ProducerLoan::empty)};let d=witness.inline_demand();let grant=grant_for(d);let mut reply=None;let((poll,_),heap)=observe(||bank.run(grant,1,|effect|{let before=effect.performed_work();drop(witness.inline_into(&mut producer,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-before})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));let step=reply.take().unwrap().unwrap();assert_eq!(bank.take_admitted(),Some(true));bank.post(step.progress(),grant,heap)}).unwrap();drop(authority);assert!(resident.empty());drop(resident);for _ in 0..10000{if source.terminal_is_empty(){break}match source.close_once().unwrap(){FixtureCloseStep::Denied|FixtureCloseStep::Blocked=>panic!("source close refused"),_=>{}}}assert!(source.terminal_is_empty());}
}
